#ifndef __GFX_FONT_H
#define __GFX_FONT_H

#include <stdint.h>

// An anti-aliased bitmap font, generated by tools/gen_fonts.py: 4-bit coverage, each glyph cropped to its ink.
namespace gfx {

struct Glyph {
    uint32_t cp;      // Unicode code point
    uint32_t off;     // byte offset of the glyph's nibbles in Font::bits (two pixels per byte, low nibble first, rows of w)
    uint8_t w, h;     // ink box
    int8_t dx;        // ink box left, from the pen position
    int8_t top;       // ink box top, in rows below the top of the line (the line is ascent + descent tall)
    uint16_t adv16;   // advance, 1/16 px
};

struct Font {
    const Glyph* glyphs;
    uint16_t count;
    const uint8_t* bits;
    uint8_t ascent, descent;
    uint8_t size;     // the CSS font-size in px

    const Glyph* find(uint32_t cp) const {
        if (cp >= 32 && cp < 127 && cp - 32 < count && glyphs[cp - 32].cp == cp) return &glyphs[cp - 32];
        for (int i = 95; i < count; ++i) if (glyphs[i].cp == cp) return &glyphs[i];
        return cp == '?' ? nullptr : find('?');
    }
    int lineHeight() const { return ascent + descent; }
};

// Next code point of a UTF-8 string; advances `s`.
inline uint32_t utf8Next(const char*& s) {
    const uint8_t c = (uint8_t)*s++;
    if (c < 0x80) return c;
    if ((c & 0xE0) == 0xC0 && *s) return ((c & 0x1Fu) << 6) | ((uint8_t)*s++ & 0x3Fu);
    if ((c & 0xF0) == 0xE0 && s[0] && s[1]) {
        const uint32_t v = ((c & 0x0Fu) << 12) | (((uint8_t)s[0] & 0x3Fu) << 6) | ((uint8_t)s[1] & 0x3Fu);
        s += 2;
        return v;
    }
    return '?';
}

}  // namespace gfx

#endif
